import React, { useState } from 'react';
import StudentList from './components/StudentList';
import AddStudent from './components/AddStudent';
import MarksForm from './components/MarksForm';
import ResultCard from './components/ResultCard';
import './index.css';

const TABS = {
  LIST: 'list',
  ADD: 'add',
  MARKS: 'marks',
  RESULT: 'result'
};

function App() {
  const [activeTab, setActiveTab] = useState(TABS.LIST);
  const [selectedStudentId, setSelectedStudentId] = useState(null);

  function viewResult(studentId) {
    setSelectedStudentId(studentId);
    setActiveTab(TABS.RESULT);
  }

  function handleMarksSubmitted(studentId) {
    viewResult(studentId);
  }

  return (
    <div className="app">
      <header className="app-header">
        <h1>Student Score Card</h1>
      </header>

      <nav className="tabs">
        <button className={activeTab === TABS.LIST ? 'active' : ''} onClick={() => setActiveTab(TABS.LIST)}>
          Students
        </button>
        <button className={activeTab === TABS.ADD ? 'active' : ''} onClick={() => setActiveTab(TABS.ADD)}>
          Add Student
        </button>
        <button className={activeTab === TABS.MARKS ? 'active' : ''} onClick={() => setActiveTab(TABS.MARKS)}>
          Enter Marks
        </button>
      </nav>

      <main className="app-main">
        {activeTab === TABS.LIST && <StudentList onViewResult={viewResult} />}
        {activeTab === TABS.ADD && <AddStudent onStudentAdded={() => setActiveTab(TABS.LIST)} />}
        {activeTab === TABS.MARKS && <MarksForm onMarksSubmitted={handleMarksSubmitted} />}
        {activeTab === TABS.RESULT && (
          <ResultCard studentId={selectedStudentId} onBack={() => setActiveTab(TABS.LIST)} />
        )}
      </main>
    </div>
  );
}

export default App;
